"""Registered signature command identity and E03 recovery, mocked models only."""
import copy,json,sys,tempfile,unittest
from pathlib import Path
from unittest.mock import Mock,patch
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from signature_probe import commands,template,compare,normalize,certificate,CLASSIFICATION
from probe_whitespace import reconcile,registered
from signature_probe_reconciliation import eligible,BASE
from orchestrate import Stop
ROOT=Path(__file__).resolve().parents[2]

class SignatureProbeTests(unittest.TestCase):
 def setUp(self):
  self.e=json.loads((ROOT/'orchestration/artifacts.json').read_text())['generated_probes']['M10B3'];self.good=template(self.e)
  self.s=dict(status='HUMAN_STOP',gate='M10B3',baseline=BASE,diagnostic='NEW_FILE_DIFF_CHECK: Probes/M10B3Signatures.lean',attempt=1,revisions=0,executor_effort_index=0,executor_history=[dict(attempt=1,gate_id='M10B3',invocation_number=1,model='gpt-5.6-sol',outcome='COMPLETED',reason='INITIAL',reasoning_effort='medium',substantive_round=1)])
 def bad(self,raw):self.assertRaises(ValueError,compare,raw,self.e)
 def test_exact_e03(self):self.assertEqual(compare(EXACT,self.e),self.good)
 def test_three_terminal_newlines(self):self.assertEqual(compare(self.good+b'\n\n\n',self.e),self.good)
 def test_canonical_unchanged(self):self.assertEqual(compare(self.good,self.e),self.good)
 def test_width(self):self.assertEqual(commands(b'set_option format.width 72\n'),[['set_option','format.width','72']])
 def test_binders(self):self.assertEqual(commands(b'set_option pp.funBinderTypes true\n'),[['set_option','pp.funBinderTypes','true']])
 def test_both(self):self.assertEqual(commands(self.good)[2:4],[['set_option','format.width','72'],['set_option','pp.funBinderTypes','true']])
 def test_changed_width(self):self.bad(self.good.replace(b'width 72',b'width 100'))
 def test_changed_boolean(self):self.bad(self.good.replace(b'funBinderTypes true',b'funBinderTypes false'))
 def test_unknown_option(self):self.bad(self.good+b'set_option pp.unknown true\n')
 def test_elaboration_option(self):self.bad(self.good+b'set_option autoImplicit false\n')
 def test_command_scoped_option(self):self.bad(self.good.replace(b'width 72',b'width 72 in'))
 def test_changed_check(self):self.bad(self.good.replace(b'#check Aiyagari1994.M10B3.PureExchangeDebt',b'#check Aiyagari1994.wrong',1))
 def test_changed_print(self):self.bad(self.good.replace(b'#check Aiyagari1994.M10B3.PureExchangeDebt',b'#print Aiyagari1994.wrong',1))
 def test_changed_axioms(self):self.bad(self.good.replace(b'#print axioms Aiyagari1994.M10B3.PureExchangeDebt',b'#print axioms Aiyagari1994.wrong',1))
 def test_print_parser_identity(self):self.assertNotEqual(commands(b'#print X\n'),commands(b'#print Y\n'))
 def test_deleted_command(self):self.bad(self.good.replace(b'#check Aiyagari1994.M10B3.PureExchangeDebt\n',b'',1))
 def test_extra_command(self):self.bad(self.good+b'#check Aiyagari1994.M10B3.PureExchangeDebt\n')
 def test_semantic_declarations(self):
  for text in ['def x := 1','theorem x : True := True.intro','lemma x : True := True.intro','axiom x : False','instance : Inhabited Nat := inferInstance','structure X','class X','opaque x : Nat']:
   with self.subTest(text=text):self.bad(self.good+text.encode()+b'\n')
 def test_prior_future_targets(self):
  for name in ['Aiyagari1994.zeroRate_cap_change_exact','Aiyagari1994.caps_above_naturalLimit_equivalent','Aiyagari1994.Release.future']:
   with self.subTest(name=name):self.bad(self.good.replace(b'Aiyagari1994.M10B3.PureExchangeDebt',name.encode()))
 def test_comments_preserved(self):
  raw=b'-- ordinary comment\n/- outer /- nested -/ block -/\n'+self.good+b'\n\n';out=compare(raw,self.e)
  self.assertEqual(commands(out),commands(self.good));self.assertTrue(out.startswith(b'-- ordinary comment'));self.assertEqual(out,raw[:-2])
 def test_inline_comment(self):
  raw=self.good.replace(b'format.width 72',b'format.width 72 -- display');self.assertEqual(commands(raw),commands(self.good));compare(raw,self.e)
 def test_whitespace_sequence(self):
  raw=self.good.replace(b'#check ',b'  #check\t').replace(b'\n',b' \t\n')+b'\n';out=compare(raw,self.e);self.assertEqual(commands(raw),commands(out))
 def test_unterminated_comment(self):self.bad(self.good+b'/-')
 def test_comments_cannot_join_tokens(self):self.bad(self.good.replace(b'#check ',b'#ch/- hidden -/eck '))
 def test_comment_hidden_command(self):self.bad(self.good+b'/- comment -/theorem x : True := True.intro\n')
 def test_no_crlf(self):self.bad(self.good.replace(b'\n',b'\r\n'))
 def test_state_identity(self):before=copy.deepcopy(self.s);eligible(self.s);self.assertEqual(before,self.s)
 def test_second_invocation(self):self.s['executor_history']*=2;self.assertRaises(Stop,eligible,self.s)
 def test_high_executor(self):self.s['executor_history'][0]['reasoning_effort']='high';self.assertRaises(Stop,eligible,self.s)
 def test_revision(self):self.s['revisions']=1;self.assertRaises(Stop,eligible,self.s)
 def test_review_started(self):self.s['snapshot_sha256']='hash';self.assertRaises(Stop,eligible,self.s)
 def fixture(self,d):
  c=Mock();c.root=Path(d);c.o=c.root/'orchestration';c.o.mkdir();c.tracked.return_value=False
  (c.o/'artifacts.json').write_text(json.dumps({'generated_probes':{'M10B3':self.e}}))
  p=c.root/self.e['path'];p.parent.mkdir();p.write_bytes(EXACT)
  a=c.root/'runtime';a.mkdir();c.attempt_directory.return_value=a;c.status.return_value=self.s
  (a/'executor_invocation.json').write_text(json.dumps(self.s['executor_history'][0]))
  (a/'executor_events.jsonl').write_text(json.dumps({'type':'item.completed','item':{'type':'file_change','status':'completed','id':'event','changes':[{'path':str(p),'kind':'add'}]}})+'\n')
  (c.root/'Audit.lean').write_bytes(self.good)
  return c,dict(id='M10B3',contracts=['E03'],signature_probe=self.e['path']),p
 def test_registered_lane_and_certificate(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);before=copy.deepcopy(self.s);r=reconcile(c,g,self.s);self.assertEqual(r['classification'],CLASSIFICATION);self.assertEqual(p.read_bytes(),self.good)
   cert=certificate(c,g);self.assertEqual(cert['result'],'PASS');self.assertEqual(cert['command_sequence'],commands(EXACT));self.assertEqual(self.s,before)
   c.model_run.assert_not_called();c.review_submission.assert_not_called()
 def test_unregistered(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);self.assertIsNone(reconcile(c,{'id':'Other'},self.s));self.assertEqual(p.read_bytes(),EXACT)
 def test_authored_file(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);g['signature_probe']='Aiyagari1994/GovernmentDebt.lean';self.assertRaises(ValueError,reconcile,c,g,self.s)
 def test_math_unchanged(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);m=c.root/'math.lean';m.write_bytes(b'theorem x : True := True.intro\n\n');b=m.read_bytes();reconcile(c,g,self.s);self.assertEqual(m.read_bytes(),b)
 def test_stale_certificate(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);reconcile(c,g,self.s);p.write_bytes(self.good+b'\n');self.assertRaises(ValueError,certificate,c,g)
 def test_audit_missing(self):
  with tempfile.TemporaryDirectory() as d:
   c,g,p=self.fixture(d);reconcile(c,g,self.s);(c.root/'Audit.lean').write_text('');self.assertRaises(ValueError,certificate,c,g)
 def test_no_review_before_context(self):
  from gate_context import validate_context
  c=Mock()
  with tempfile.TemporaryDirectory() as d:self.assertRaises(Exception,validate_context,Path(d),c,{'id':'M10B3'},'base')
  c.model_run.assert_not_called()

